import json
d = json.load(open('behavioral-diffs.json'))
for e in d:
    if 'expense' in e['key'].lower() or 'hourly-rate' in e['key'].lower() or 'cost-rate' in e['key'].lower():
        print('===', e['key'])
        c = e.get('corrected') or {}
        print(' corrected opId:', c.get('operationId'))
        print(' corrected responses:', json.dumps(c.get('responses'), indent=1)[:800])
        print(' corrected params:', [p.get('name') for p in (c.get('parameters') or [])])
        print(' corrected live-status:', c.get('x-clockify-live-status'))
EOF"
}

